    if (N <= 1) {
        return 0;
    }
    // The time required equals the largest even number <= N.
    return N - (N & 1);
}

public static int calculateTimeNeeded(int N) {
    // If there are fewer than 3 people, no time is needed to reverse the order.
    if (N <= 2) {
        return 0;
    }
    // For N >= 3, the time in minutes grows linearly as 2*(N-3).
    return 2 * (N - 3);
}

