            continue; // cannot be twice another integer if not even
        }
        int other = val / 2;
        if (!freq.containsKey(other)) {
            continue;
        }
        if (other == val) {
            // Need at least two copies to consider each a double of another
            if (entry.getValue() >= 2) {
                result += entry.getValue();
            }
        } else {
            result += entry.getValue();
        }
    }
    return result;
}

public static int countDoubles(int[] numbers) {
    if (numbers == null || numbers.length == 0) {
        return 0;
    }
    java.util.Set<Integer> set = new java.util.HashSet<>();
    for (int num : numbers) {
        set.add(num);
    }
    int count = 0;
    for (int num : numbers) {
        if (num % 2 == 0) {
            int half = num / 2;
            if (set.contains(half)) {
                count++;
            }
        }
    }
    return count;
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    int sx = start[0], sy = start[1];
    int ex = end[0], ey = end[1];
    if (sx < 0 || sx >= n || sy < 0 || sy >= n || ex < 0 || ex >= n || ey < 0 || ey >= n) {
        return "cannot be travelled";
    }
    // If start equals end, it's trivially reachable
    if (sx == ex && sy == ey) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1];
            int x2 = p[2], y2 = p[3];
            if (x1 < 0 || x1 >= n || y1 < 0 || y1 >= n || x2 < 0 || x2 >= n || y2 < 0 || y2 >= n) {
                continue;
            }
            // Check if the two points are adjacent (Manhattan distance of 1)
            if (Math.abs(x1 - x2) + Math.abs(y1 - y2) != 1) {
                continue;
            }
            String a = x1 + "," + y1;
            String b = x2 + "," + y2;
            adj.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            adj.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    String startKey = sx + "," + sy;
    queue.offer(startKey);
    visited.add(startKey);
    String targetKey = ex + "," + ey;

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(targetKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = adj.get(cur);
        if (neighbors != null) {
            for (String nb : neighbors) {
                if (!visited.contains(nb)) {
                    visited.add(nb);
                    queue.offer(nb);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input dimensions
    if (n <= 0) {
        return "cannot be travelled";
    }
    if (start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    // Helper to generate a unique string key from coordinate array
    java.util.function.Function<int[], String> keyFunc = coord -> {
        java.lang.StringBuilder sb = new java.lang.StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adjacency = new java.util.HashMap<>();
    if (paths != null) {
        for (int[] path : paths) {
            if (path == null || path.length != 2 * n) {
                continue; // skip invalid entries
            }
            int[] src = new int[n];
            int[] tgt = new int[n];
            System.arraycopy(path, 0, src, 0, n);
            System.arraycopy(path, n, tgt, 0, n);
            String srcKey = keyFunc.apply(src);
            String tgtKey = keyFunc.apply(tgt);
            adjacency.computeIfAbsent(srcKey, k -> new java.util.ArrayList<>()).add(tgtKey);
            adjacency.computeIfAbsent(tgtKey, k -> new java.util.ArrayList<>()).add(srcKey);
        }
    }
    // Breadth-first search
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    visited.add(startKey);
    queue.add(startKey);
    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adjacency.get(current);
        if (neighbors == null) {
            continue;
        }
        for (String neighbor : neighbors) {
            if (visitorContains(visited, neighbor)) {
                continue;
            }
            if (neighbor.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(neighbor);
            queue.add(neighbor);
        }
    }
    return "cannot be travelled";
}

private static boolean visitorContains(java.util.Set<String> visited, String key) {
    return visited.contains(key);
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Validate input
    if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int dim = start.length;
    if (end.length != dim) {
        return "cannot be travelled";
    }

    // Helper to create a key for a coordinate
    java.util.function.Function<int[], String> keyFunc = p -> {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < p.length; i++) {
            if (i > 0) sb.append('#');
            sb.append(p[i]);
        }
        return sb.toString();
    };

    // Check start and end bounds
    for (int i = 0; i < dim; i++) {
        if (start[i] < 0 || start[i] >= n || end[i] < 0 || end[i] >= n) {
            return "cannot be travelled";
        }
    }

    // If start equals end
    boolean same = true;
    for (int i = 0; i < dim; i++) {
        if (start[i] != end[i]) {
            same = false;
            break;
        }
    }
    if (same) {
        return "can be travelled";
    }

    // Build adjacency list
    java.util.Map<String, java.util.Set<String>> adj = new java.util.HashMap<>();
    for (int[] path : paths) {
        if (path == null || path.length != 2 * dim) {
            continue; // invalid path entry
        }
        int[] a = new int[dim];
        int[] b = new int[dim];
        for (int i = 0; i < dim; i++) {
            a[i] = path[i];
            b[i] = path[dim + i];
        }
        // Verify bounds
        boolean valid = true;
        for (int i = 0; i < dim; i++) {
            if (a[i] < 0 || a[i] >= n || b[i] < 0 || b[i] >= n) {
                valid = false;
                break;
            }
        }
        if (!valid) continue;
        // Verify adjacency (difference of 1 in exactly one coordinate)
        int diff = 0;
        for (int i = 0; i < dim; i++) {
            int d = Math.abs(a[i] - b[i]);
            if (d > 1) {
                diff = -1;
                break;
            } else if (d == 1) {
                diff++;
            }
        }
        if (diff != 1) continue; // not adjacent
        String ka = keyFunc.apply(a);
        String kb = keyFunc.apply(b);
        adj.computeIfAbsent(ka, k -> new java.util.HashSet<>()).add(kb);
        adj.computeIfAbsent(kb, k -> new java.util.HashSet<>()).add(ka);
    }

    // BFS
    java.util.Queue<int[]> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    String startKey = keyFunc.apply(start);
    String endKey = keyFunc.apply(end);
    queue.offer(start);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        int[] cur = queue.poll();
        String curKey = keyFunc.apply(cur);
        java.util.Set<String> neighbors = adj.get(curKey);
        if (neighbors == null) continue;
        for (String nbKey : neighbors) {
            if (visited.contains(nbKey)) continue;
            if (nbKey.equals(endKey)) {
                return "can be travelled";
            }
            visited.add(nbKey);
            // Convert key back to int[]
            String[] parts = nbKey.split("#");
            int[] nb = new int[dim];
            for (int i = 0; i < dim; i++) {
                nb[i] = Integer.parseInt(parts[i]);
            }
            queue.offer(nb);
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Basic validation
    if (n <= 0 || start == null || end == null || start.length != n || end.length != n) {
        return "cannot be travelled";
    }
    if (paths == null) {
        // If no paths, only travel possible if start==end
        return java.util.Arrays.equals(start, end) ? "can be travelled" : "cannot be travelled";
    }

    // Helper to convert coordinate array to a unique string key
    java.util.function.Function<int[], String> coordKey = (int[] coord) -> {
        if (coord == null || coord.length != n) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < coord.length; i++) {
            if (i > 0) sb.append(',');
            sb.append(coord[i]);
        }
        return sb.toString();
    };

    String startKey = coordKey.apply(start);
    String endKey = coordKey.apply(end);
    if (startKey == null || endKey == null) {
        return "cannot be travelled";
    }

    // Build adjacency map
    java.util.Map<String, java.util.List<String>> adj = new java.util.HashMap<>();

    for (int i = 0; i < paths.length; i++) {
        int[] path = paths[i];
        if (path == null || path.length != 2 * n) {
            // Skip invalid path specification
            continue;
        }
        int[] p1 = new int[n];
        int[] p2 = new int[n];
        System.arraycopy(path, 0, p1, 0, n);
        System.arraycopy(path, n, p2, 0, n);
        String key1 = coordKey.apply(p1);
        String key2 = coordKey.apply(p2);
        if (key1 == null || key2 == null) {
            continue;
        }
        adj.computeIfAbsent(key1, k -> new java.util.ArrayList<>()).add(key2);
        adj.computeIfAbsent(key2, k -> new java.util.ArrayList<>()).add(key1);
    }

    // Edge case: start==end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // BFS
    java.util.Queue<String> queue = new java.util.ArrayDeque<>();
    java.util.Set<String> visited = new java.util.HashSet<>();

    queue.offer(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = adj.getOrDefault(current, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (!visited.contains(nb)) {
                if (nb.equals(endKey)) {
                    return "can be travelled";
                }
                visited.add(nb);
                queue.offer(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    try {
        if (n <= 0) return "cannot be travelled";
        if (start == null || end == null || start.length != n || end.length != n) return "cannot be travelled";
        // Helper to convert coordinate to string
        java.util.function.Function<int[], String> coordToStr = (int[] coord) -> {
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < coord.length; i++) {
                if (i > 0) sb.append(',');
                sb.append(coord[i]);
            }
            return sb.toString();
        };
        String startStr = coordToStr.apply(start);
        String endStr = coordToStr.apply(end);
        if (startStr.equals(endStr)) return "can be travelled";

        java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
        if (paths != null) {
            for (int[] path : paths) {
                if (path == null || path.length != 2 * n) return "cannot be travelled";
                int[] a = new int[n];
                int[] b = new int[n];
                System.arraycopy(path, 0, a, 0, n);
                System.arraycopy(path, n, b, 0, n);
                String aStr = coordToStr.apply(a);
                String bStr = coordToStr.apply(b);
                graph.computeIfAbsent(aStr, k -> new java.util.ArrayList<>()).add(bStr);
                graph.computeIfAbsent(bStr, k -> new java.util.ArrayList<>()).add(aStr);
            }
        }

        java.util.Set<String> visited = new java.util.HashSet<>();
        java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
        queue.add(startStr);
        visited.add(startStr);
        while (!queue.isEmpty()) {
            String cur = queue.poll();
            java.util.List<String> neighbors = graph.get(cur);
            if (neighbors != null) {
                for (String nb : neighbors) {
                    if (nb.equals(endStr)) return "can be travelled";
                    if (!visited.contains(nb)) {
                        visited.add(nb);
                        queue.add(nb);
                    }
                }
            }
        }
        return "cannot be travelled";
    } catch (Exception e) {
        return "cannot be travelled";
    }
}

public static String convertDatesToWeekdays(String date) {
    if (date == null || date.trim().isEmpty()) {
        throw new IllegalArgumentException("Input date string cannot be null or empty.");
    }

    String[] parts = date.trim().split("\\s+");
    if (parts.length != 3) {
        throw new IllegalArgumentException("Input must be in format 'MM dd yyyy'.");
    }

    int month, day, year;
    try {
        month = Integer.parseInt(parts[0]);
        day = Integer.parseInt(parts[1]);
        year = Integer.parseInt(parts[2]);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("Month, day, and year must be numeric.", e);
    }

    // Validate month range
    if (month < 1 || month > 12) {
        throw new IllegalArgumentException("Month must be between 01 and 12.");
    }

    // Validate day using LocalDate (throws if invalid)
    java.time.LocalDate localDate;
    try {
        localDate = java.time.LocalDate.of(year, month, day);
    } catch (java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid date: " + e.getMessage(), e);
    }

    // Get full month name
    String[] monthNames = {
        "", "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    };
    String monthName = monthNames[month];

    // Get weekday name
    java.time.DayOfWeek dayOfWeek = localDate.getDayOfWeek();
    String weekday = dayOfWeek.toString().toLowerCase();
    weekday = Character.toUpperCase(weekday.charAt(0)) + weekday.substring(1);

    return monthName + " " + day + ", " + year + " is a " + weekday;
}

