}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int total = 0;
    for (int v : nums) total += v;
    // dp[k] -> set of sums of subsets with k elements
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] dp = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = new java.util.HashSet<>();
    }
    dp[0].add(0);
    for (int num : nums) {
        // iterate k descending to avoid reuse of same element in the same round
        for (int k = Math.min(n - 1, n); k >= 1; k--) {
            for (int sum : dp[k - 1]) {
                int newSum = sum + num;
                dp[k].add(newSum);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((total * k) % n != 0) continue;
        int target = (total * k) / n;
        if (dp[k].contains(target)) return true;
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    if (nums == null || nums.length <= 1) {
        return false;
    }
    int n = nums.length;
    int total = 0;
    for (int v : nums) total += v;

    // reachable[size] contains all achievable sums using exactly 'size' elements
    java.util.List<java.util.Set<Integer>> reachable = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        reachable.add(new java.util.HashSet<>());
    }
    reachable.get(0).add(0);

    for (int num : nums) {
        // iterate sizes in reverse to avoid using updated states in the same iteration
        for (int size = Math.min(n, reachable.size() - 1); size >= 1; size--) {
            java.util.Set<Integer> prevSet = reachable.get(size - 1);
            if (prevSet.isEmpty()) continue;
            java.util.Set<Integer> currSet = reachable.get(size);
            for (int prevSum : prevSet) {
                currSet.add(prevSum + num);
            }
        }
    }

    for (int k = 1; k <= n / 2; k++) {
        long prod = (long) total * k;
        if (prod % n != 0) continue;
        int target = (int) (prod / n);
        if (reachable.get(k).contains(target)) {
            return true;
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input cost array cannot be null");
    }
    int n = cost.length;
    switch (n) {
        case 0:
            return 0;
        case 1:
            // If there's only one step, we can start on a higher step and pay nothing
            return 0;
        default:
            // We only need to keep track of the last two computed values
            int twoBack = cost[0];
            int oneBack = cost[1];
            int current = 0;
            for (int i = 2; i < n; i++) {
                current = Math.min(twoBack, oneBack) + cost[i];
                twoBack = oneBack;
                oneBack = current;
            }
            return Math.min(twoBack, oneBack);
    }
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array 'cost' cannot be null.");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int first = 0;  // dp[i-2]
    int second = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(first + cost[i - 2], second + cost[i - 1]);
        first = second;
        second = cur;
    }
    return second;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("cost array cannot be null");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        // With only one step, you can start on step 0 and reach the top without paying the cost of that step.
        return 0;
    }
    int prev = 0; // cost to reach step i-2
    int curr = 0; // cost to reach step i-1
    for (int i = 0; i < n; i++) {
        int newCost = Math.min(prev, curr) + cost[i];
        prev = curr;
        curr = newCost;
    }
    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null) {
        throw new IllegalArgumentException("Input array cannot be null.");
    }
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev2 = cost[0];      // dp[i-2]
    int prev1 = cost[1];      // dp[i-1]
    for (int i = 2; i < n; i++) {
        int current = Math.min(prev1, prev2) + cost[i];
        prev2 = prev1;
        prev1 = current;
    }
    return Math.min(prev1, prev2);
}

public int minCostClimbingStairs(int[] cost) {
    // Validate input
    if (cost == null) {
        throw new IllegalArgumentException("cost array must not be null");
    }

    int n = cost.length;

    // Edge cases
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }

    // Use two variables to keep track of the minimum cost to reach the two
    // previous steps. This reduces memory usage from O(n) to O(1).
    int prev2 = cost[0]; // cost to reach step 0
    int prev1 = cost[1]; // cost to reach step 1

    // Iterate from step 2 to the last step
    for (int i = 2; i < n; i++) {
        int current = cost[i] + Math.min(prev1, prev2);
        prev2 = prev1;
        prev1 = current;
    }

    // The answer is the minimum of the two last computed costs
    return Math.min(prev1, prev2);
}

