public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }

    int maxEnd = nums[0];
    int maxGlobal = nums[0];
    int minEnd = nums[0];
    int minGlobal = nums[0];

    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];

        // Update maximum subarray ending at current position
        maxEnd = Math.max(val, maxEnd + val);
        maxGlobal = Math.max(maxGlobal, maxEnd);

        // Update minimum subarray ending at current position
        minEnd = Math.min(val, minEnd + val);
        minGlobal = Math.min(minGlobal, minEnd);
    }

    // The maximum absolute sum is the larger of maximum sum or absolute value of minimum sum
    return Math.max(maxGlobal, -minGlobal);
}

public int maxAbsoluteSum(int[] nums) {
    // Handle null or empty input
    if (nums == null || nums.length == 0) {
        return 0;
    }
    // Use long to avoid integer overflow during accumulation
    long maxEndingHere = nums[0];
    long maxSoFar = nums[0];
    long minEndingHere = nums[0];
    long minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        // Max subarray sum ending at i
        maxEndingHere = Math.max(val, maxEndingHere + val);
        maxSoFar = Math.max(maxSoFar, maxEndingHere);
        // Min subarray sum ending at i
        minEndingHere = Math.min(val, minEndingHere + val);
        minSoFar = Math.min(minSoFar, minEndingHere);
    }
    long absMax = Math.abs(maxSoFar);
    long absMin = Math.abs(minSoFar);
    long result = Math.max(absMax, absMin);
    // The problem expects an int return type.
    // If the result exceeds Integer bounds, clamp it.
    if (result > Integer.MAX_VALUE) {
        return Integer.MAX_VALUE;
    } else if (result < Integer.MIN_VALUE) {
        return Integer.MIN_VALUE;
    }
    return (int) result;
}

