}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    int limit = (int) Math.sqrt(n);
    int[] small = new int[limit + 1];
    int[] large = new int[limit + 1];
    int smallCount = 0;
    int largeCount = 0;
    for (int i = 1; i <= limit; i++) {
        if (n % i == 0) {
            small[smallCount++] = i;
            int other = n / i;
            if (other != i) {
                large[largeCount++] = other;
            }
        }
    }
    // Reverse the large array to ascending order
    for (int i = 0; i < largeCount / 2; i++) {
        int temp = large[i];
        large[i] = large[largeCount - 1 - i];
        large[largeCount - 1 - i] = temp;
    }
    int total = smallCount + largeCount;
    if (k > total) {
        return -1;
    }
    if (k <= smallCount) {
        return small[k - 1];
    } else {
        int idx = k - smallCount - 1;
        return large[idx];
    }
}

