    int sqrt = (int)Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                big.add(other);
            }
        }
    }
    java.util.Collections.reverse(big);
    small.addAll(big);
    if (k > small.size()) return -1;
    return small.get(k - 1);
}

