public String makeGood(String s) {
    // Handle null input defensively
    if (s == null) {
        return null;
    }
    // Use a StringBuilder as a stack to build the final good string
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int n = stack.length();
        if (n > 0 && Math.abs(c - stack.charAt(n - 1)) == 32) {
            // Adjacent characters cancel each other (case-insensitive match)
            stack.setLength(n - 1); // pop
        } else {
            stack.append(c); // push
        }
    }
    return stack.toString();
}

public String makeGood(String s) {
    if (s == null) {
        return null;
    }
    java.util.Deque<Character> stack = new java.util.ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (!stack.isEmpty()) {
            char top = stack.peek();
            if (Character.toLowerCase(top) == Character.toLowerCase(c) && top != c) {
                stack.pop();
                continue;
            }
        }
        stack.push(c);
    }
    StringBuilder sb = new StringBuilder();
    while (!stack.isEmpty()) {
        sb.append(stack.removeLast());
    }
    return sb.toString();
}

