        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) { // is same letter opposite case
                stack.setLength(len - 1); // pop
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int[] max = {0};
    java.util.HashSet<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, max);
    return max[0];
}

private void dfs(String s, int index, java.util.HashSet<String> used, int[] max) {
    if (index == s.length()) {
        if (used.size() > max[0]) {
            max[0] = used.size();
        }
        return;
    }
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!used.contains(sub)) {
            used.add(sub);
            dfs(s, end, used, max);
            used.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int[] best = new int[]{0};
    java.util.HashSet<String> seen = new java.util.HashSet<>();
    backtrack(s, 0, seen, 0, best);
    return best[0];
}

private void backtrack(String s, int pos, java.util.HashSet<String> seen, int count, int[] best) {
    if (pos == s.length()) {
        if (count > best[0]) {
            best[0] = count;
        }
        return;
    }
    // If the number of remaining characters plus current count can't beat best, prune
    if (count + (s.length() - pos) <= best[0]) {
        // theoretical maximum substrings is each single char
        return;
    }
    for (int end = pos + 1; end <= s.length(); end++) {
        String sub = s.substring(pos, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            backtrack(s, end, seen, count + 1, best);
            seen.remove(sub);
        }
    }
}

public int maxUniqueSplit(String s) {
