    }
    try {
        return dfs(0, s, new java.util.HashSet<>());
    } catch (Exception e) {
        // In case of unexpected errors, return 0 as a fallback
        return 0;
    }
}

private int dfs(int index, String s, java.util.Set<String> seen) {
    if (index == s.length()) {
        return 0;
    }
    int maxCount = 0;
    for (int end = index + 1; end <= s.length(); end++) {
        String sub = s.substring(index, end);
        if (!seen.contains(sub)) {
            seen.add(sub);
            int current = 1 + dfs(end, s, seen);
            if (current > maxCount) {
                maxCount = current;
            }
            seen.remove(sub);
        }
    }
    return maxCount;
}

public int maxUniqueSplit(String s) {
