    for (String log : logs) {
        if (log == null) {
            // Skip null entries
            continue;
        }

        switch (log) {
            case "../":
                if (depth > 0) {
                    depth--;
                }
                break;
            case "./":
                // Stay in the current directory; no change to depth
                break;
            default:
                // Any other string is considered a directory entry
                // We only increment depth if the string is non-empty
                if (!log.isEmpty()) {
                    depth++;
                }
                break;
        }
    }

    return depth;
}

