    if (logs == null || logs.length == 0) {
        return 0;
    }
    int depth = 0;
    for (String op : logs) {
        if (op == null) {
            continue; // ignore null entries
        }
        if (op.equals("../")) {
            // Move up one level, but never go above root
            depth = Math.max(depth - 1, 0);
        } else if (op.equals("./")) {
            // No change in depth
            continue;
        } else if (op.endsWith("/") /* typical folder name */) {
            // Enter a new subfolder
            depth++;
        } else {
            // For any other strings, treat them as valid subfolders to be safe
            depth++;
        }
    }
    // Depth represents how many levels away we are from the main folder
    return depth;
}

