public String getSmallestString(int n, int k) {
    if (n <= 0) {
        return "";
    }
    if (k < n || k > 26L * n) {
        // Impossible to construct a string with given constraints.
        return "";
    }
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }
    int remaining = k - n; // amount of value to distribute beyond the 'a's
    int index = n - 1;
    while (remaining > 0 && index >= 0) {
        int add = Math.min(25, remaining); // max we can add to a single character
        result[index] = (char) ('a' + add);
        remaining -= add;
        index--;
    }
    return new String(result);
}

