public static int singleNumber(int[] nums) {
    if (nums == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    int ones = 0;   // Bits which have appeared once modulo 3
    int twos = 0;   // Bits which have appeared twice modulo 3
    for (int num : nums) {
        // When num bit is 1:
        //   - If bit was already in ones, it goes to twos
        //   - If bit was already in twos, it will be cleared from both
        int newTwos = twos | (ones & num);
        int newOnes = ones ^ num;
        int mask = ~(newOnes & newTwos);
        ones = newOnes & mask;
        twos = newTwos & mask;
    }
    return ones;
}

