public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) return result;
    Set<Long> visited = new HashSet<>();
    Queue<Long> queue = new LinkedList<>();

    for (int seed = 0; seed <= 9; seed++) {
        long start = seed;
        if (start > high) continue;
        queue.offer(start);
        visited.add(start);
    }

    while (!queue.isEmpty()) {
        long curr = queue.poll();
        if (curr >= low && curr <= high) {
            result.add((int)curr);
        }
        long lastDigit = curr % 10;
        if (curr == 0) { // special case: from 0 only generate 1
            long next = curr * 10 + 1;
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
            continue;
        }
        // generate next by lastDigit-1
        if (lastDigit > 0) {
            long next = curr * 10 + (lastDigit - 1);
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
        // generate next by lastDigit+1
        if (lastDigit < 9) {
            long next = curr * 10 + (lastDigit + 1);
            if (next <= high && !visited.contains(next)) {
                visited.add(next);
                queue.offer(next);
            }
        }
    }

    Collections.sort(result);
    return result;
}

