public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }

    // Include 0 if within range
    if (low <= 0 && 0 <= high) {
        result.add(0);
    }

    // Queue for BFS generation, use long to avoid overflow
    Queue<Long> queue = new LinkedList<>();

    // Initialize queue with single-digit numbers 1-9
    for (int i = 1; i <= 9; i++) {
        if (i <= high) {
            queue.offer((long) i);
        }
    }

    while (!queue.isEmpty()) {
        long current = queue.poll();
        if (current > high) {
            continue;
        }
        if (current >= low) {
            result.add((int) current);
        }
        int lastDigit = (int) (current % 10);
        // Next possible digits
        int[] nextDigits = new int[2];
        nextDigits[0] = lastDigit - 1;
        nextDigits[1] = lastDigit + 1;
        for (int next : nextDigits) {
            if (next < 0 || next > 9) {
                continue;
            }
            long nextNumber = current * 10 + next;
            if (nextNumber <= high) {
                queue.offer(nextNumber);
            }
        }
    }

    Collections.sort(result);
    return result;
}

