public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    if (n == 0) {
        return 0;
    }
    // Validate matrix shape and values
    for (int i = 0; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must be non‑null and of equal length");
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] != 0 && mat[i][j] != 1) {
                throw new IllegalArgumentException("Matrix may only contain 0s and 1s");
            }
        }
    }
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j + 1 < n ? anti[i - 1][j + 1] : 0) + 1;
                int currentMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                           Math.max(diag[i][j], anti[i][j]));
                if (currentMax > max) {
                    max = currentMax;
                }
            } else {
                horiz[i][j] = vert[i][j] = diag[i][j] = anti[i][j] = 0;
            }
        }
    }
    return max;
}

