    int[][] diag = new int[m][n];
    int[][] anti = new int[m][n];
    int max = 0;

    for (int i = 0; i < m; i++) {
        // In case of a jagged matrix, skip rows with wrong length
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must have the same length");
        }
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                up[i][j] = (i > 0 ? up[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                int current = Math.max(Math.max(left[i][j], up[i][j]), Math.max(diag[i][j], anti[i][j]));
                if (current > max) max = current;
            } else {
                left[i][j] = up[i][j] = diag[i][j] = anti[i][j] = 0;
