public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    // Verify that all rows have the same length to avoid IndexOutOfBounds
    for (int i = 1; i < m; i++) {
        if (mat[i] == null || mat[i].length != n) {
            throw new IllegalArgumentException("All rows must be non-null and have the same length.");
        }
    }
    int total = m * n;
    int[] result = new int[total];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int start = Math.max(0, d - (n - 1));
        int end = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int i = end; i >= start; i--) {
                int j = d - i;
                result[idx++] = mat[i][j];
            }
        } else {
            for (int i = start; i <= end; i++) {
                int j = d - i;
                result[idx++] = mat[i][j];
            }
        }
    }
    return result;
}

