    int index = 0;

    // We will process each diagonal defined by the sum of indices (i + j)
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = sum < m ? sum : m - 1;
        int startCol = sum - startRow;

        // Determine direction: even sums go upwards, odd sums go downwards
        if (sum % 2 == 0) {
            // Move up-left: decrement row, increment col
            int row = startRow;
            int col = startCol;
            while (row >= 0 && col < n) {
                result[index++] = mat[row][col];
                row--;
                col++;
            }
        } else {
            // Move down-right: increment row, decrement col
            int row = startRow;
            int col = startCol;
            while (col >= 0 && row < m) {
                result[index++] = mat[row][col];
                row++;
                col--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    // Handle null or empty matrix
    if (mat == null || mat.length == 0) {
        return new int[0];
    }
    int m = mat.length;
    // Determine maximum possible sum of indices
    int maxSum = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) continue;
        int n = mat[i].length;
        if (n == 0) continue;
        maxSum = Math.max(maxSum, i + n - 1);
    }
    // If all rows are empty, return empty array
    if (maxSum == 0 && (mat[0] == null || mat[0].length == 0)) {
        return new int[0];
    }
    // Map sum of indices to the list of elements
    java.util.Map<Integer, java.util.List<Integer>> bucket = new java.util.HashMap<>();
    int total = 0;
    for (int i = 0; i < m; i++) {
        if (mat[i] == null) continue;
        int n = mat[i].length;
        for (int j = 0; j < n; j++) {
            int sum = i + j;
            bucket.computeIfAbsent(sum, k -> new java.util.ArrayList<>()).add(mat[i][j]);
            total++;
        }
    }
    int[] result = new int[total];
    int idx = 0;
    // Build the answer using the bucket information
    java.util.List<Integer> curr;
    for (int sum = 0; sum <= maxSum; sum++) {
        curr = bucket.get(sum);
        if (curr == null) continue;
        if ((sum & 1) == 0) { // even sum -> reverse order
            for (int k = curr.size() - 1; k >= 0; k--) {
                result[idx++] = curr.get(k);
            }
        } else { // odd sum -> normal order
            for (int val : curr) {
                result[idx++] = val;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int total = m * n;
    int[] result = new int[total];
    int index = 0;
    for (int s = 0; s <= m + n - 2; ++s) {
        // Determine the start row and column
        int startRow = Math.max(0, s - n + 1);
        int endRow = Math.min(m - 1, s);
        if (s % 2 == 0) {
            // bottom-up: iterate from endRow down to startRow
            for (int r = endRow; r >= startRow; --r) {
                int c = s - r;
                result[index++] = mat[r][c];
            }
        } else {
            // top-down: iterate from startRow up to endRow
            for (int r = startRow; r <= endRow; ++r) {
                int c = s - r;
                result[index++] = mat[r][c];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;
    // Step 1: find the first index i from right where digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) { // no higher permutation
        return -1;
    }
    // Step 2: find j, the smallest digit greater than digits[i] to the right
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    // Step 3: swap i and j
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    // Step 4: reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }
    // Convert back to number with overflow check
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // overflow, cannot represent in int
        }
    }
    return (int) result;
}

