    }

    // Step 2: Find the rightmost successor to pivot that is greater than digits[pivot]
    int successor = -1;
    for (int j = len - 1; j > pivot; j--) {
        if (digits[j] > digits[pivot]) {
            successor = j;
            break;
        }
    }
    // Swap pivot and successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 3: Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, handling potential overflow
    try {
