private static List<String> generateStrobogrammatic(int current, int totalLength) {
    List<String> result = new ArrayList<>();
    if (current == 0) {
        result.add("");
        return result;
    }
    if (current == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    List<String> inner = generateStrobogrammatic(current - 2, totalLength);
    for (String s : inner) {
        if (totalLength != current) {
            result.add("0" + s + "0");
        }
        result.add("1" + s + "1");
        result.add("6" + s + "9");
        result.add("8" + s + "8");
        result.add("9" + s + "6");
    }
    return result;
}

