private static List<String> buildStrobogrammatic(int len, int original) {
    if (len == 0) {
        List<String> base = new ArrayList<>();
        base.add("");
        return base;
    }
    if (len == 1) {
        List<String> base = new ArrayList<>();
        base.add("0");
        base.add("1");
        base.add("8");
        return base;
    }

    List<String> inner = buildStrobogrammatic(len - 2, original);
    List<String> results = new ArrayList<>();

    char[] first = { '0', '1', '6', '8', '9' };
    char[] second = { '0', '1', '9', '8', '6' };

    for (String sub : inner) {
        for (int i = 0; i < first.length; i++) {
            if (len == original && first[i] == '0') {
                continue; // avoid leading zero
            }
            results.add(first[i] + sub + second[i]);
        }
    }
    return results;
}

