public static boolean isBoomerang(int[][] points) {
    // Validate input: must be non-null and contain exactly three 2D points
    if (points == null || points.length != 3) {
        return false;
    }

    // Retrieve each point with bounds checks
    int[] p1 = points[0];
    int[] p2 = points[1];
    int[] p3 = points[2];
    if (p1 == null || p2 == null || p3 == null ||
        p1.length < 2 || p2.length < 2 || p3.length < 2) {
        return false;
    }

    // Use long to avoid int overflow in cross‐product calculation
    long x1 = p1[0], y1 = p1[1];
    long x2 = p2[0], y2 = p2[1];
    long x3 = p3[0], y3 = p3[1];

    long cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

    // Non‑zero cross product indicates the points are not colinear,
    // thus they form a boomerang.
    return cross != 0;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        // Validate each point and check for duplicates
        for (int i = 0; i < 3; i++) {
            if (points[i] == null || points[i].length < 2) {
                return false;
            }
            for (int j = i + 1; j < 3; j++) {
                if (points[j] == null || points[j].length < 2) {
                    return false;
                }
                if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                    return false; // duplicate point
                }
            }
        }

        int x1 = points[0][0], y1 = points[0][1];
        int x2 = points[1][0], y2 = points[1][1];
        int x3 = points[2][0], y3 = points[2][1];

        // Compute twice the signed area of triangle (collinearity test)
        long area = (long) (x2 - x1) * (y3 - y1) - (long) (x3 - x1) * (y2 - y1);
        return area != 0;
    } catch (Exception e) {
        // Any unexpected error results in a non-boomerang
        return false;
    }
}

