public static int calculateEnergy(String s) {
    // Return 0 for null or empty input as there is no non-empty substring
    if (s == null || s.isEmpty()) {
        return 0;
    }

    int maxLen = 1; // longest run seen so far
    int currentLen = 1; // length of the current run

    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            currentLen++; // extend current run
        } else {
            currentLen = 1; // start new run
        }
        if (currentLen > maxLen) {
            maxLen = currentLen;
        }
    }

    return maxLen;
}

