public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.HashSet<Integer> unique = new java.util.HashSet<>();
    java.util.HashSet<Integer> duplicates = new java.util.HashSet<>();
    for (int num : nums) {
        if (duplicates.contains(num)) {
            continue; // already known duplicate, skip
        }
        if (unique.contains(num)) {
            unique.remove(num);
            duplicates.add(num);
        } else {
            unique.add(num);
        }
    }
    long sum = 0;
    for (int val : unique) {
        sum += val;
    }
    // Cast to int, truncating if overflow occurs
    return (int) sum;
}

