        for (int k = 1; k * k <= i; k++) {
            int sq = k * k;
            if (dp[i - sq] + 1 < dp[i]) {
                dp[i] = dp[i - sq] + 1;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        throw new IllegalArgumentException("n must be non‑negative");
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    java.util.Arrays.fill(dp, Integer.MAX_VALUE);
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int prev = dp[i - square];
            if (prev != Integer.MAX_VALUE && prev + 1 < dp[i]) {
                dp[i] = prev + 1;
            }
        }
    }
