}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            result.append(word.reverse());
            word.setLength(0);
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (if any)
    result.append(word.reverse());

    return result.toString();
}

public static String reverseWords(String s) {
    // Handle null input gracefully
    if (s == null) {
        return null;
    }

    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c != ' ') {
            // Accumulate characters of the current word
            currentWord.append(c);
        } else {
            // Encountered a space: reverse collected word and append
            result.append(currentWord.reverse());
            result.append(' ');
            currentWord.setLength(0); // reset for the next word
        }
    }

    // Append the last word if the string didn't end with a space
    if (currentWord.length() > 0) {
        result.append(currentWord.reverse());
    }

    return result.toString();
}

